#[derive(Debug)]
pub struct ImmuneBuffDataPayload {
    pub header_tag: u8,
    pub flag: u8,
    pub entries: (u32, Vec<u8>),
    pub trailing: u8,
}
impl ImmuneBuffDataPayload {
    pub fn read_from(data: &[u8], offset: &mut usize) -> io::Result<Self> {
        let header_tag = u8::read_from(data, offset)?;
        let flag = u8::read_from(data, offset)?;
        let entries = { let count = u32::read_from(data, offset)?; let elem_size: usize = match header_tag { 0 => 1, 1 => 4, 2 => 4, 3 => 4, 4 => 0, 5 => 8, _ => return Err(io::Error::new(io::ErrorKind::InvalidData, format!("unknown header tag for entries: {}", header_tag))) }; let total = (count as usize) * elem_size; let mut body = vec![0u8; total]; for x in &mut body { *x = u8::read_from(data, offset)?; } (count, body) };
        let trailing = u8::read_from(data, offset)?;
        Ok(Self { header_tag, flag, entries, trailing })
    }
    pub fn write_to(&self, w: &mut dyn Write) -> io::Result<()> {
        self.header_tag.write_to(w)?;
        self.flag.write_to(w)?;
        { self.entries.0.write_to(w)?; w.write_all(&self.entries.1)?; }
        self.trailing.write_to(w)?;
        Ok(())
    }
}

